-- ============================================================
-- KalsaTrack - Define Missing Leon Project Routes
-- Generated from scripts/leon_fmr_projects_live.json and barangay_geocode_cache.json
-- Routes were requested from OSRM road-network geometry.
-- Keep project_length_km as the declared project length; mapped_length_km records generated geometry length.
-- Ayubo, Baje, Biri Sur, Salngan, Talacuan, and Tunguan use barangay profile coordinate overrides.
-- ============================================================

CREATE TABLE IF NOT EXISTS public.project_routes (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  project_id BIGINT NOT NULL UNIQUE REFERENCES public.fmr_projects(id) ON DELETE CASCADE,
  start_latitude DOUBLE PRECISION,
  start_longitude DOUBLE PRECISION,
  end_latitude DOUBLE PRECISION,
  end_longitude DOUBLE PRECISION,
  route_points JSONB DEFAULT '[]'::jsonb,
  route_source TEXT DEFAULT 'manual',
  route_quality TEXT DEFAULT 'approximate',
  declared_length_km DOUBLE PRECISION,
  mapped_length_km DOUBLE PRECISION,
  road_gap_km DOUBLE PRECISION,
  road_gap_type TEXT,
  road_gap_reason TEXT,
  created_at TIMESTAMPTZ DEFAULT now(),
  updated_at TIMESTAMPTZ DEFAULT now()
);

ALTER TABLE public.project_routes ADD COLUMN IF NOT EXISTS route_source TEXT DEFAULT 'manual';
ALTER TABLE public.project_routes ADD COLUMN IF NOT EXISTS route_quality TEXT DEFAULT 'approximate';
ALTER TABLE public.project_routes ADD COLUMN IF NOT EXISTS declared_length_km DOUBLE PRECISION;
ALTER TABLE public.project_routes ADD COLUMN IF NOT EXISTS mapped_length_km DOUBLE PRECISION;
ALTER TABLE public.project_routes ADD COLUMN IF NOT EXISTS road_gap_km DOUBLE PRECISION;
ALTER TABLE public.project_routes ADD COLUMN IF NOT EXISTS road_gap_type TEXT;
ALTER TABLE public.project_routes ADD COLUMN IF NOT EXISTS road_gap_reason TEXT;

ALTER TABLE public.fmr_projects ADD COLUMN IF NOT EXISTS road_gap_km DOUBLE PRECISION;
ALTER TABLE public.fmr_projects ADD COLUMN IF NOT EXISTS road_gap_type TEXT;
ALTER TABLE public.fmr_projects ADD COLUMN IF NOT EXISTS road_gap_reason TEXT;

ON CONFLICT (project_id) DO UPDATE SET
  start_latitude = EXCLUDED.start_latitude,
  start_longitude = EXCLUDED.start_longitude,
  end_latitude = EXCLUDED.end_latitude,
  end_longitude = EXCLUDED.end_longitude,
  route_points = EXCLUDED.route_points,
  route_source = EXCLUDED.route_source,
  route_quality = EXCLUDED.route_quality,
  declared_length_km = EXCLUDED.declared_length_km,
  mapped_length_km = EXCLUDED.mapped_length_km,
  road_gap_km = EXCLUDED.road_gap_km,
  road_gap_type = EXCLUDED.road_gap_type,
  road_gap_reason = EXCLUDED.road_gap_reason,
  updated_at = now();

-- Keep fmr_projects start/end columns aligned for older views that do not read project_routes first.
UPDATE public.fmr_projects AS p
SET
  start_latitude = r.start_latitude,
  start_longitude = r.start_longitude,
  end_latitude = r.end_latitude,
  end_longitude = r.end_longitude
FROM public.project_routes AS r
WHERE p.id = r.project_id
  AND p.id IN (
    201, 203, 204, 207, 209, 210, 211, 212, 214, 215, 217, 218, 219, 222, 223, 225, 226, 227, 228, 229, 231, 232, 233, 236, 237, 238, 239, 240, 242, 243, 244, 245, 247, 248, 249, 250, 253, 254, 255, 256, 257, 258, 259, 260, 261, 262, 263, 264, 266, 269, 271, 272, 274, 275, 276, 278, 282, 283, 284, 285, 287, 288, 289, 291, 292, 293, 294, 296, 297, 299, 302, 306, 307, 308, 309, 310, 311, 312, 313, 314, 316, 317, 318, 320, 321, 324, 326, 327, 328, 329, 330, 332, 333, 334, 335
  );

UPDATE public.fmr_projects AS p
SET
  road_gap_km = r.road_gap_km,
  road_gap_type = r.road_gap_type,
  road_gap_reason = r.road_gap_reason
FROM public.project_routes AS r
WHERE p.id = r.project_id
  AND r.road_gap_km IS NOT NULL;

-- Explicit gap metadata for prioritized projects, including projects whose GPS route already existed.
UPDATE public.fmr_projects AS p
SET
  road_gap_km = gaps.road_gap_km,
  road_gap_type = gaps.road_gap_type,
  road_gap_reason = gaps.road_gap_reason
FROM (VALUES
  (201::bigint, 1.44::double precision, 'Earth Surface Gap'::text, 'Agboy Norte-Siol Norte has 98% earth surface in poor condition, creating a priority market-access gap.'::text),
  (206::bigint, 2.6::double precision, 'Gravel Surface Gap'::text, 'Avanzada-Baje has a long gravel/poor-condition portion that weakens all-weather connectivity.'::text),
  (219::bigint, 2.28::double precision, 'Earth Surface Gap'::text, 'Binolbog-Ambulong is recorded as fully earth surfaced and poor, a clear missing paved link.'::text),
  (226::bigint, 3.44::double precision, 'Mixed Earth/Gravel Gap'::text, 'Bucari-Cagay-Ingay has combined earth and gravel sections that constrain highland access.'::text),
  (228::bigint, 2.11::double precision, 'Critical Earth Gap'::text, 'Bucari-Cumpan-Sibucao is recorded as a critical earth road gap.'::text),
  (231::bigint, 2.47::double precision, 'Mixed Earth/Gravel Gap'::text, 'Buga-Sitio Dao-Baong has mostly earth and gravel surface, affecting rainy-season access.'::text),
  (232::bigint, 3.68::double precision, 'Mixed Earth/Gravel Gap'::text, 'Buga-Kananghan-Iguaras has a long unpaved section suitable for gap-based prioritization.'::text),
  (236::bigint, 1.9::double precision, 'Earth Surface Gap'::text, 'Buga-Sitio Tibod-Lanag is recorded as fully earth surfaced in poor condition.'::text),
  (257::bigint, 2.49::double precision, 'Gravel Surface Gap'::text, 'Dorog-Cawilihan has a long gravel segment that can delay produce movement.'::text),
  (295::bigint, 2::double precision, 'Gravel Surface Gap'::text, 'Malublub-Sitio Lintian is fully gravel surfaced and can justify improvement priority.'::text),
  (297::bigint, 1.82::double precision, 'Earth Surface Gap'::text, 'Malublub-Sitio Tumotob is recorded as fully earth surfaced and poor.'::text),
  (334::bigint, 1.44::double precision, 'Earth Surface Gap'::text, 'Tu-og-Siol Norte is recorded as a full earth surface gap.'::text)
) AS gaps(project_id, road_gap_km, road_gap_type, road_gap_reason)
WHERE p.id = gaps.project_id;

-- Generated 95 route definitions.
-- Snap mode: OSRM road-network requested.
-- Explicit road gap projects: 12.
